from __future__ import annotations
import math
from typing import Callable, Tuple

def eml_quad_approx(h: float, x: float) -> float:
    """Single-exponential EML network (2/h^2)(exp(h x)-1-h x) ~ x^2."""
    if h <= 0.0:
        raise ValueError('h must be positive')
    return (2.0/(h*h)) * (math.exp(h*x) - 1.0 - h*x)

def build_quadratic_network(epsilon: float
                            ) -> Tuple[Callable[[float], float], float, float]:
    """Return (network, h, certified_bound) meeting sup error <= epsilon."""
    h = min(1.0, (9.0/4.0) * epsilon)
    certified = (4.0/9.0) * h
    return (lambda x: eml_quad_approx(h, x)), h, certified

def sup_error_on_unit_interval(h: float, samples: int = 2001) -> float:
    return max(abs(eml_quad_approx(h, i/(samples-1)) - (i/(samples-1))**2)
               for i in range(samples))
